import string

def reverse_get_tbl_entry(trans_tbl, transformed):
    mapping = {}
    for i in range(0, len(trans_tbl), 2):
        mapping[trans_tbl[i+1]] = trans_tbl[i]
    return mapping.get(transformed, None)

def main():
    # Reconstructed trans_tbl based on guessed logic
    trans_tbl = bytearray([0x01, 0x41, 0x02, 0x42, 0x03, 0x43, 0x04, 0x44])  # Example. Use actual reconstructed tbl.

    # Expected flag transformation from main function
    transformed = bytearray([
        0xb1, 0xe7, 0x11, 0xf5, 0x9d, 0x73, 0xb3, 0x27,
        0x30, 0xf4, 0xf9, 0xf9, 0xb3, 0x99, 0xbe, 0xb3,
        0xb1, 0x99, 0x65, 0x23, 0x73, 0x99, 0x71, 0x1b,
        0xf9, 0x27, 0x99, 0x23, 0xbe, 0x11, 0x11, 0x65])

    reconstructed_flag = ""
    for char in transformed:
        original = reverse_get_tbl_entry(trans_tbl, char)
        if original is None:
            print(f"Error: No reverse mapping for byte {char:02x}")
            return
        reconstructed_flag += chr(original)

    print(f"Reconstructed Flag: {reconstructed_flag}")

if __name__ == "__main__":
    main()

